<?php require 'config.php';if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: contact.html');exit;}verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$subject=trim($_POST['subject']??'');$message=trim($_POST['message']??'');if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$subject||!$message){exit('Please fill all fields. <a href="contact.html">Back</a>');}$uid=$_SESSION['user']['id']??null;$q=$pdo->prepare('INSERT INTO contact_messages(user_id,name,email,subject,message) VALUES(?,?,?,?,?)');$q->execute([$uid,$name,$email,$subject,$message]);header('Location: contact.html?submitted=1');exit;?>